files.src/cart.ts:
import type { Product } from "../../catalog-api/src/contracts";

export function subtotal(product: Product, quantity: number): number {
  return product.priceCents * quantity;
}

export function displayPrice(product: Product): string {
  return product["priceCents"] + " " + product.currency;
}

export function localVariable(product: Product): number {
  const { priceCents } = product;
  return priceCents;
}

