export interface AdBid { priceCents: number }
export function bidValue(bid: AdBid): number {
  return bid.priceCents;
}

files.src/order.ts:
import type { Product } from "../../catalog-api/src/contracts";
import { subtotal } from "../../storefront/src/cart";

export function charge(product: Product): number {
  const { priceCents: unitPrice } = product;
  return subtotal(product, 2) + unitPrice;
}

export function createLine(priceCents: number): Product {
  return { id: "sku-2048", priceCents, currency: "EUR" };
}

